mkdir -p /tmp/scripts_cap && cat > /tmp/scripts_cap/count.py <<'EOF'
import csv, sys
d = sys.argv[1]
plans = {r["plan"]: int(r["requests_per_minute"]) for r in csv.DictReader(open(f"{d}/plan_limits.csv"))}
factors = {r["region"]: float(r["factor"]) for r in csv.DictReader(open(f"{d}/region_factors.csv"))}
changed = {}
for r in csv.DictReader(open(f"{d}/accounts.csv")):
    scaled = int(plans[r["plan"]] * factors[r["region"]])
    capped = min(scaled, 20) if r["plan"] == "free" and r["region"] in {"ap-south", "sa-east"} else scaled
    if capped != scaled:
        changed[(r["region"], scaled)] = changed.get((r["region"], scaled), 0) + 1
print(changed, sum(changed.values()))
